const supa = (table) => `${SUPABASE_URL}/rest/v1/${table}`;
const headers = {
  "apikey": SUPABASE_KEY,
  "Authorization": `Bearer ${SUPABASE_KEY}`,
  "Content-Type": "application/json",
  "Prefer": "return=representation"
};

const DB = {
  async getAll(table) {
    try {
      const r = await fetch(`${supa(table)}?select=*&order=created_at.desc`, { headers });
      return r.ok ? await r.json() : [];
    } catch { return []; }
  },
  async insert(table, data) {
    try {
      const r = await fetch(supa(table), { method:"POST", headers, body:JSON.stringify(data) });
      const res = await r.json();
      return r.ok ? res[0] : null;
    } catch { return null; }
  },
  async update(table, id, data) {
    try {
      const r = await fetch(`${supa(table)}?id=eq.${id}`, { method:"PATCH", headers, body:JSON.stringify(data) });
      const res = await r.json();
      return r.ok ? res[0] : null;
    } catch { return null; }
  },
  async delete(table, id) {
    try {
      const r = await fetch(`${supa(table)}?id=eq.${id}`, { method:"DELETE", headers });
      return r.ok;
    } catch { return false; }
  },
  async getByField(table, field, value) {
    try {
      const r = await fetch(`${supa(table)}?${field}=eq.${encodeURIComponent(value)}&limit=1`, { headers });
      const res = await r.json();
      return r.ok && res.length > 0 ? res[0] : null;
    } catch { return null; }
  },
  async getAllByField(table, field, value) {
    try {
      const r = await fetch(`${supa(table)}?${field}=eq.${encodeURIComponent(value)}`, { headers });
      return r.ok ? await r.json() : [];
    } catch { return []; }
  },
  async deleteByField(table, field, value) {
    try {
      const r = await fetch(`${supa(table)}?${field}=eq.${encodeURIComponent(value)}`, { method:"DELETE", headers });
      return r.ok;
    } catch { return false; }
  },
  async insertMany(table, rows) {
    try {
      const r = await fetch(supa(table), { method:"POST", headers, body:JSON.stringify(rows) });
      return r.ok;
    } catch { return false; }
  }
};

