// ============================================================
// LOGIN SCREEN
// ============================================================
const LoginScreen = ({ onLogin }) => {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const handleLogin = async () => {
    if (!username.trim()||!password.trim()) { setError("Preencha todos os campos"); return; }
    setLoading(true); setError("");
    try {
      const user = await DB.getByField("users","username",username.trim().toLowerCase());
      if (!user) { setError("Usuário não encontrado"); setLoading(false); return; }
      const h = await hashPassword(password);
      if (h !== user.password_hash) { setError("Senha incorreta"); setLoading(false); return; }
      onLogin(user);
    } catch { setError("Erro ao conectar. Verifique sua internet."); }
    setLoading(false);
  };

  return (
    <div style={{ display:"flex",alignItems:"center",justifyContent:"center",minHeight:"100vh",padding:20,background:`radial-gradient(ellipse at 30% 20%,rgba(185,37,50,.04) 0%,transparent 60%),radial-gradient(ellipse at 70% 80%,rgba(242,140,35,.03) 0%,transparent 60%),${T.bg}` }}>
      <div style={{ background:T.surface,border:`1px solid ${T.border}`,borderRadius:20,padding:"48px 40px",width:"100%",maxWidth:420,boxShadow:T.shadow }}>
        <div style={{ textAlign:"center",marginBottom:32 }}>
          <img src={LOGO} alt="Dux Logistics" style={{ height:60,marginBottom:20,borderRadius:8 }}/>
          <div style={{ fontSize:22,fontWeight:700,letterSpacing:"-.3px",color:T.text }}>DISC Candidatos</div>
          <div style={{ fontSize:14,color:T.textSec }}>Acesse o painel de RH</div>
        </div>
        {error && <div style={errBox}>{error}</div>}
        <label style={labelS}>Usuário</label>
        <input style={input} placeholder="seu.usuario" value={username} onChange={e=>setUsername(e.target.value)} onKeyDown={e=>e.key==="Enter"&&handleLogin()} onFocus={focusH} onBlur={blurH}/>
        <label style={labelS}>Senha</label>
        <input style={input} type="password" placeholder="••••••••" value={password} onChange={e=>setPassword(e.target.value)} onKeyDown={e=>e.key==="Enter"&&handleLogin()} onFocus={focusH} onBlur={blurH}/>
        <button style={{ ...btnP,width:"100%",opacity:loading?.6:1 }} onClick={handleLogin} disabled={loading}>{loading?"Entrando...":"Entrar"}</button>
        <div style={{ textAlign:"center",marginTop:24,fontSize:12,color:T.textMut }}>Primeiro acesso? Peça ao administrador para criar sua conta.</div>
      </div>
    </div>
  );
};

