// ============================================================
// MODAL: CHANGE OWN PASSWORD
// ============================================================
const ChangePasswordModal = ({ currentUser, onClose }) => {
  const [currentPw, setCurrentPw] = useState("");
  const [newPw, setNewPw] = useState("");
  const [confirmPw, setConfirmPw] = useState("");
  const [error, setError] = useState("");
  const [success, setSuccess] = useState(false);
  const [saving, setSaving] = useState(false);

  const handleSave = async () => {
    setError("");
    if (!currentPw || !newPw || !confirmPw) { setError("Preencha todos os campos"); return; }
    if (newPw.length < 4) { setError("A nova senha deve ter pelo menos 4 caracteres"); return; }
    if (newPw !== confirmPw) { setError("A confirmação não confere com a nova senha"); return; }
    setSaving(true);
    const user = await DB.getByField("users", "id", currentUser.id);
    const currentHash = await hashPassword(currentPw);
    if (!user || currentHash !== user.password_hash) { setError("Senha atual incorreta"); setSaving(false); return; }
    const newHash = await hashPassword(newPw);
    await DB.update("users", currentUser.id, { password_hash: newHash });
    setSaving(false);
    setSuccess(true);
    setTimeout(onClose, 1800);
  };

  return (
    <Modal onClose={onClose}>
      <div style={{ fontSize:20,fontWeight:700,marginBottom:4 }}>Alterar Senha</div>
      <div style={{ fontSize:13,color:T.textSec,marginBottom:28 }}>Atualize a senha de acesso da sua conta</div>
      {error && <div style={errBox}>{error}</div>}
      {success ? (
        <div style={{ ...errBox,background:T.successLight,color:T.success,borderColor:T.success }}>Senha alterada com sucesso!</div>
      ) : (
        <>
          <label style={labelS}>Senha atual *</label>
          <input style={input} type="password" placeholder="••••••••" value={currentPw} onChange={e=>setCurrentPw(e.target.value)} onFocus={focusH} onBlur={blurH}/>
          <label style={labelS}>Nova senha *</label>
          <input style={input} type="password" placeholder="••••••••" value={newPw} onChange={e=>setNewPw(e.target.value)} onFocus={focusH} onBlur={blurH}/>
          <label style={labelS}>Confirmar nova senha *</label>
          <input style={input} type="password" placeholder="••••••••" value={confirmPw} onChange={e=>setConfirmPw(e.target.value)}
            onFocus={focusH} onBlur={blurH} onKeyDown={e=>{if(e.key==="Enter")handleSave();}}/>
          <div style={{ display:"flex",gap:12 }}>
            <button style={{ ...btnO,flex:1 }} onClick={onClose}>Cancelar</button>
            <button style={{ ...btnP,flex:1,opacity:saving?.6:1 }} onClick={handleSave} disabled={saving}>{saving?"Salvando...":"Salvar Nova Senha"}</button>
          </div>
        </>
      )}
    </Modal>
  );
};

// ============================================================
// MODAL: NEW USER (RH)
// ============================================================
const UserModal = ({ onClose, onSave, editUser }) => {
  const [form, setForm] = useState(editUser ? { username:editUser.username, name:editUser.name, password:"", role:editUser.role||"rh" } : { username:"",name:"",password:"",role:"rh" });
  const [error, setError] = useState("");
  const [saving, setSaving] = useState(false);
  const isEdit = !!editUser;

  const handleSave = async () => {
    if (!form.name.trim()||!form.username.trim()) { setError("Preencha nome e usuário"); return; }
    if (!isEdit && !form.password.trim()) { setError("Defina uma senha para o novo usuário"); return; }
    setSaving(true);
    const uname = form.username.trim().toLowerCase();
    if (!isEdit) {
      const ex = await DB.getByField("users","username",uname);
      if (ex) { setError("Usuário já existe"); setSaving(false); return; }
    }
    if (isEdit) {
      const updates = { name:form.name.trim(), role:form.role };
      if (form.password) updates.password_hash = await hashPassword(form.password);
      await DB.update("users", editUser.id, updates);
    } else {
      const hashed = await hashPassword(form.password);
      await DB.insert("users", { id:uname, username:uname, name:form.name.trim(), password_hash:hashed, role:form.role });
    }
    setSaving(false);
    onSave();
  };

  return (
    <Modal onClose={onClose}>
      <div style={{ fontSize:20,fontWeight:700,marginBottom:4 }}>{isEdit?"Editar Usuário":"Novo Usuário"}</div>
      <div style={{ fontSize:13,color:T.textSec,marginBottom:28 }}>Pessoas que podem acessar o painel</div>
      {error && <div style={errBox}>{error}</div>}
      <label style={labelS}>Nome completo *</label>
      <input style={input} placeholder="Nome" value={form.name} onChange={e=>setForm({...form,name:e.target.value})} onFocus={focusH} onBlur={blurH}/>
      <label style={labelS}>Usuário *</label>
      <input style={{ ...input, ...(isEdit?{background:T.bg,cursor:"not-allowed"}:{}) }} placeholder="usuario.login" value={form.username} disabled={isEdit} onChange={e=>setForm({...form,username:e.target.value})} onFocus={focusH} onBlur={blurH}/>
      <label style={labelS}>Perfil de acesso *</label>
      <select style={select} value={form.role} onChange={e=>setForm({...form,role:e.target.value})}>
        <option value="rh">RH — gera links e vê candidatos</option>
        <option value="admin">Administrador — RH + gerencia usuários</option>
      </select>
      <label style={labelS}>{isEdit?"Nova senha (deixe em branco para manter)":"Senha *"}</label>
      <input style={input} type="password" placeholder="••••••••" value={form.password} onChange={e=>setForm({...form,password:e.target.value})} onFocus={focusH} onBlur={blurH}/>
      <div style={{ display:"flex",gap:12 }}>
        <button style={{ ...btnO,flex:1 }} onClick={onClose}>Cancelar</button>
        <button style={{ ...btnP,flex:1,opacity:saving?.6:1 }} onClick={handleSave} disabled={saving}>{saving?"Salvando...":"Salvar"}</button>
      </div>
    </Modal>
  );
};

// ============================================================
// MODAL: NEW CANDIDATE (generate link)
// ============================================================
const NewCandidateModal = ({ onClose, onSave, currentUser, vagasExistentes }) => {
  const [vaga, setVaga] = useState("");
  const [empresa, setEmpresa] = useState("");
  const [error, setError] = useState("");
  const [saving, setSaving] = useState(false);
  const [created, setCreated] = useState(null);
  const [copied, setCopied] = useState(false);

  const handleCreate = async () => {
    if (!empresa) { setError("Selecione a empresa do grupo"); return; }
    setError("");
    setSaving(true);
    const id = genId();
    await DB.insert("candidates", { id, vaga:vaga.trim(), empresa, status:"Pendente", created_by:currentUser.id });
    setSaving(false);
    setCreated(id);
  };

  const link = created ? `${window.location.origin}${window.location.pathname}?token=${created}` : "";

  const handleCopy = async () => {
    try { await navigator.clipboard.writeText(link); setCopied(true); setTimeout(()=>setCopied(false),2000); } catch {}
  };

  const handleEmail = () => {
    const to = prompt("E-mail do candidato:");
    if (!to) return;
    const subject = "Teste de Perfil Comportamental — Dux Logistics";
    const body = `Olá,\n\nVocê está participando do nosso processo seletivo na Dux Logistics.\n\nPor favor, acesse o link abaixo para realizar o teste de perfil comportamental (leva cerca de 10 minutos):\n\n${link}\n\nAtenciosamente,\nEquipe de Recrutamento e Seleção\nDux Logistics`;
    window.location.href = `mailto:${encodeURIComponent(to)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
  };

  return (
    <Modal onClose={onClose}>
      {!created ? (
        <>
          <div style={{ fontSize:20,fontWeight:700,marginBottom:4 }}>Gerar Link para Candidato</div>
          <div style={{ fontSize:13,color:T.textSec,marginBottom:28 }}>O candidato vai informar nome, CPF e e-mail ao abrir o link</div>
          {error && <div style={errBox}>{error}</div>}
          <label style={labelS}>Empresa do grupo *</label>
          <select style={select} value={empresa} onChange={e=>setEmpresa(e.target.value)}>
            <option value="">Selecione a empresa</option>
            {EMPRESAS_DUX.map(e => <option key={e} value={e}>{e}</option>)}
          </select>
          <label style={labelS}>Vaga (opcional)</label>
          <input style={input} list="vagas-datalist" placeholder="Selecione uma vaga existente ou digite uma nova" value={vaga} onChange={e=>setVaga(e.target.value)} onFocus={focusH} onBlur={blurH}/>
          <datalist id="vagas-datalist">
            {(vagasExistentes||[]).map(v => <option key={v} value={v}/>)}
          </datalist>
          <div style={{ display:"flex",gap:12 }}>
            <button style={{ ...btnO,flex:1 }} onClick={onClose}>Cancelar</button>
            <button style={{ ...btnP,flex:1,opacity:saving?.6:1 }} onClick={handleCreate} disabled={saving}>{saving?"Gerando...":"Gerar Link"}</button>
          </div>
        </>
      ) : (
        <>
          <div style={{ fontSize:20,fontWeight:700,marginBottom:4 }}>Link gerado! ✅</div>
          <div style={{ fontSize:13,color:T.textSec,marginBottom:20 }}>Copie o link ou envie direto por e-mail para o candidato</div>
          <div style={{ background:T.bg,border:`1px solid ${T.border}`,borderRadius:T.radSm,padding:"12px 14px",marginBottom:20,fontSize:13,wordBreak:"break-all",color:T.textSec }}>{link}</div>
          <div style={{ display:"flex",gap:12,marginBottom:12 }}>
            <button style={{ ...btnO,flex:1 }} onClick={handleCopy}>{copied?"Copiado!":"Copiar Link"}</button>
            <button style={{ ...btnP,flex:1 }} onClick={handleEmail}>Enviar por E-mail</button>
          </div>
          <button style={{ ...btnO,width:"100%" }} onClick={()=>{onSave();onClose();}}>Concluir</button>
        </>
      )}
    </Modal>
  );
};

// ============================================================
// MODAL: VIEW RESULT
// ============================================================
// ============================================================
// HELPER: DOWNLOAD RESULT AS DOCUMENT (via print)
// ============================================================
const discColorsMap = {D:"#C0392B",I:"#F39C12",S:"#27AE60",C:"#2980B9"};

const downloadResultDocument = (candidate, result) => {
  const w = window.open("", "_blank");
  if (!w) { alert("Permita pop-ups para baixar o documento."); return; }
  const buildProfileBlock = (view) => {
    const scores = view==="mais" ? result.scores_mais : result.scores_menos;
    const winner = view==="mais" ? result.perfil_mais : result.perfil_menos;
    const prof = DISC_PROFILES[winner];
    const bars = ["D","I","S","C"].map(k => `
      <div style="display:inline-flex;flex-direction:column;align-items:center;gap:6px;margin:0 14px;">
        <div style="width:34px;height:80px;background:#F1EEE9;border-radius:8px;position:relative;overflow:hidden;border:1px solid #E5E0D8;">
          <div style="position:absolute;bottom:0;left:0;right:0;height:${(scores[k]/25)*100}%;background:${discColorsMap[k]};"></div>
        </div>
        <div style="font-weight:700;font-size:13px;color:${discColorsMap[k]};">${k}</div>
        <div style="font-weight:600;font-size:11px;color:#6B6B6B;">${scores[k]}</div>
      </div>`).join("");
    return `
      <div style="border:1px solid #E5E0D8;border-radius:14px;padding:24px;margin-bottom:16px;text-align:center;">
        <div style="font-size:11px;font-weight:700;color:#9B9B9B;text-transform:uppercase;letter-spacing:1.5px;margin-bottom:10px;">${view==="mais"?"O que mais o descreve":"O que menos o descreve"}</div>
        <div style="width:60px;height:60px;border-radius:16px;background:${prof.color};display:inline-flex;align-items:center;justify-content:center;font-size:26px;font-weight:800;color:#fff;margin-bottom:10px;">${winner}</div>
        <div style="font-size:19px;font-weight:700;">${prof.name}</div>
        <div style="color:#6B6B6B;font-size:12px;margin-bottom:16px;">${prof.sub}</div>
        <div>${bars}</div>
      </div>`;
  };
  w.document.write(`
    <html><head><title>Resultado — ${candidate.name}</title>
    <meta charset="utf-8"/>
    <style>
      body{font-family:Arial,Helvetica,sans-serif;color:#2C2C2C;padding:40px;max-width:640px;margin:0 auto;}
      h1{font-size:22px;margin-bottom:4px;}
      .sub{color:#6B6B6B;font-size:13px;margin-bottom:24px;}
      .info{background:#F7F5F2;border-radius:12px;padding:16px 20px;margin-bottom:24px;font-size:13px;line-height:1.8;}
      .info b{display:inline-block;width:110px;color:#6B6B6B;}
      @media print { body{padding:20px;} }
    </style>
    </head><body>
      <h1>Resultado — Teste de Perfil Comportamental (DISC)</h1>
      <div class="sub">Dux Logistics — Processo Seletivo</div>
      <div class="info">
        <div><b>Nome:</b> ${candidate.name}</div>
        <div><b>CPF:</b> ${formatCpf(candidate.cpf)}</div>
        <div><b>E-mail:</b> ${candidate.email}</div>
        ${candidate.empresa?`<div><b>Empresa:</b> ${candidate.empresa}</div>`:""}
        ${candidate.vaga?`<div><b>Vaga:</b> ${candidate.vaga}</div>`:""}
        <div><b>Respondido em:</b> ${fmtDateTime(candidate.answered_at)}</div>
      </div>
      ${buildProfileBlock("mais")}
      ${buildProfileBlock("menos")}
    </body></html>
  `);
  w.document.close();
  setTimeout(() => { w.print(); }, 400);
};

