// MODAL: VIEW ANSWERS (25 questions detail)
// ============================================================
const AnswersModal = ({ candidate, onClose }) => {
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    (async () => {
      const r = await DB.getByField("disc_results", "candidate_id", candidate.id);
      setResult(r);
      setLoading(false);
    })();
  }, [candidate.id]);

  return (
    <Modal onClose={onClose}>
      <div style={{ fontSize:20,fontWeight:700,marginBottom:4 }}>Respostas de {candidate.name}</div>
      <div style={{ fontSize:13,color:T.textSec,marginBottom:20 }}>As 25 respostas do teste, palavra por palavra</div>
      {loading ? (
        <div style={{ color:T.textMut,fontSize:14 }}>Carregando...</div>
      ) : !result || !result.answers ? (
        <div style={errBox}>Detalhamento de respostas não disponível para este candidato.</div>
      ) : (
        <div style={{ maxHeight:440,overflowY:"auto",display:"flex",flexDirection:"column",gap:10 }}>
          {result.answers.map((a,i) => (
            <div key={i} style={{ border:`1px solid ${T.border}`,borderRadius:10,padding:"10px 14px" }}>
              <div style={{ fontSize:11,color:T.textMut,fontWeight:600,marginBottom:6 }}>PERGUNTA {a.id}</div>
              <div style={{ display:"flex",flexWrap:"wrap",gap:8 }}>
                {a.opcoes.map((o,oi) => {
                  const isMais = a.mais && a.mais.palavra===o.palavra;
                  const isMenos = a.menos && a.menos.palavra===o.palavra;
                  return (
                    <span key={oi} style={{
                      padding:"5px 12px",borderRadius:20,fontSize:12,fontWeight:600,
                      background: isMais?T.successLight:isMenos?T.dangerLight:T.bg,
                      color: isMais?T.success:isMenos?T.danger:T.textSec,
                      border:`1px solid ${isMais?T.success:isMenos?T.danger:T.border}`
                    }}>
                      {o.palavra}{isMais?" ✓ mais":isMenos?" ✗ menos":""}
                    </span>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      )}
      <div style={{ marginTop:20,textAlign:"right" }}><button style={btnO} onClick={onClose}>Fechar</button></div>
    </Modal>
  );
};

const ResultModal = ({ candidate, onClose }) => {
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(true);
  const [view, setView] = useState("mais");

  useEffect(() => {
    (async () => {
      const r = await DB.getByField("disc_results", "candidate_id", candidate.id);
      setResult(r);
      setLoading(false);
    })();
  }, [candidate.id]);

  const discColors = {D:"#C0392B",I:"#F39C12",S:"#27AE60",C:"#2980B9"};

  return (
    <Modal onClose={onClose}>
      <div style={{ fontSize:20,fontWeight:700,marginBottom:4 }}>{candidate.name}</div>
      <div style={{ fontSize:13,color:T.textSec,marginBottom:20 }}>
        CPF: {formatCpf(candidate.cpf)} • {candidate.email}{candidate.empresa?` • ${candidate.empresa}`:""}{candidate.vaga?` • Vaga: ${candidate.vaga}`:""}
      </div>
      {loading ? (
        <div style={{ color:T.textMut,fontSize:14 }}>Carregando resultado...</div>
      ) : !result ? (
        <div style={errBox}>Resultado não encontrado.</div>
      ) : (
        <>
          <div style={{ display:"flex",gap:8,marginBottom:20 }}>
            {["mais","menos"].map(v => (
              <button key={v} onClick={()=>setView(v)} style={{ padding:"8px 16px",borderRadius:20,fontSize:13,fontWeight:600,border:`1.5px solid ${view===v?T.primary:T.border}`,background:view===v?T.primaryLight:"transparent",color:view===v?T.primary:T.textSec,cursor:"pointer",fontFamily:T.font }}>
                {v==="mais"?"Mais o descreve":"Menos o descreve"}
              </button>
            ))}
          </div>
          {(() => {
            const scores = view==="mais" ? result.scores_mais : result.scores_menos;
            const winner = view==="mais" ? result.perfil_mais : result.perfil_menos;
            const prof = DISC_PROFILES[winner];
            return (
              <div style={{ background:T.bg,borderRadius:16,padding:28,textAlign:"center" }}>
                <div style={{ width:72,height:72,borderRadius:20,background:prof.color,display:"inline-flex",alignItems:"center",justifyContent:"center",fontSize:32,fontWeight:800,color:"#fff",marginBottom:12 }}>{winner}</div>
                <div style={{ fontSize:22,fontWeight:700 }}>{prof.name}</div>
                <div style={{ color:T.textSec,fontSize:13,marginBottom:24 }}>{prof.sub}</div>
                <div style={{ display:"flex",justifyContent:"center",gap:16 }}>
                  {["D","I","S","C"].map(k => (
                    <div key={k} style={{ display:"flex",flexDirection:"column",alignItems:"center",gap:6 }}>
                      <div style={{ width:36,height:90,background:"#FFF",borderRadius:8,position:"relative",overflow:"hidden",border:`1px solid ${T.border}` }}>
                        <div style={{ position:"absolute",bottom:0,left:0,right:0,height:`${(scores[k]/25)*100}%`,background:discColors[k],borderRadius:8 }}/>
                      </div>
                      <div style={{ fontWeight:700,fontSize:13,color:discColors[k] }}>{k}</div>
                      <div style={{ fontWeight:600,fontSize:12,color:T.textSec }}>{scores[k]}</div>
                    </div>
                  ))}
                </div>
              </div>
            );
          })()}
          <div style={{ fontSize:12,color:T.textMut,marginTop:16 }}>Teste respondido em {fmtDateTime(candidate.answered_at)}</div>
        </>
      )}
      <div style={{ marginTop:24,display:"flex",justifyContent:"flex-end",gap:12 }}>
        {result && <button style={btnP} onClick={()=>downloadResultDocument(candidate,result)}>Baixar Resultado</button>}
        <button style={btnO} onClick={onClose}>Fechar</button>
      </div>
    </Modal>
  );
};

