// PAGE: DASHBOARD
// ============================================================
const DashboardPage = ({ candidates }) => {
  const total = candidates.length;
  const respondidos = candidates.filter(c=>c.status==="Respondido").length;
  const pendentes = total - respondidos;

  return (
    <div>
      <div style={pageTitle}>Dashboard</div>
      <div style={pageSub}>Visão geral do processo seletivo</div>
      <div style={{ display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(180px,1fr))",gap:16,marginBottom:32 }}>
        {[
          { v:total, l:"Total de Convites", c:T.primary },
          { v:respondidos, l:"Respondidos", c:T.success },
          { v:pendentes, l:"Pendentes", c:T.warning },
        ].map((s,i) => (
          <div key={i} style={{ background:T.surface,border:`1px solid ${T.border}`,borderRadius:T.rad,padding:"24px 20px",borderTop:`3px solid ${s.c}` }}>
            <div style={{ fontSize:32,fontWeight:700,letterSpacing:"-1px",fontFamily:T.mono,color:s.c }}>{s.v}</div>
            <div style={{ fontSize:12,color:T.textSec,marginTop:4,textTransform:"uppercase",letterSpacing:".5px" }}>{s.l}</div>
          </div>
        ))}
      </div>
      <div style={card}>
        <div style={{ fontSize:16,fontWeight:600,marginBottom:12 }}>Últimos Candidatos</div>
        {candidates.slice(0,8).length === 0 ? (
          <div style={{ color:T.textMut,fontSize:14 }}>Nenhum candidato ainda.</div>
        ) : candidates.slice(0,8).map(c => (
          <div key={c.id} style={{ display:"flex",justifyContent:"space-between",padding:"10px 0",borderBottom:`1px solid ${T.border}`,fontSize:14 }}>
            <span>{c.name || <span style={{ color:T.textMut }}>Convite pendente</span>}</span>
            <span style={badge(c.status==="Respondido"?"Positivo":"Para melhorar")}>{c.status}</span>
          </div>
        ))}
      </div>
    </div>
  );
};

// ============================================================
// PAGE: CANDIDATES
// ============================================================
const CandidatesPage = ({ candidates, onRefresh, currentUser, isAdmin }) => {
  const [showNew, setShowNew] = useState(false);
  const [viewResult, setViewResult] = useState(null);
  const [viewAnswers, setViewAnswers] = useState(null);
  const [deleteC, setDeleteC] = useState(null);
  const [filterStatus, setFilterStatus] = useState("Todos");
  const [filterEmpresa, setFilterEmpresa] = useState("Todas");
  const [filterVaga, setFilterVaga] = useState("Todas");
  const [search, setSearch] = useState("");
  const [msg, setMsg] = useState("");
  const [downloadingId, setDownloadingId] = useState(null);

  const vagasList = [...new Set(candidates.map(c=>c.vaga).filter(Boolean))].sort((a,b)=>a.localeCompare(b));

  const filtered = candidates.filter(c => {
    if (filterStatus !== "Todos" && c.status !== filterStatus) return false;
    if (filterEmpresa !== "Todas" && c.empresa !== filterEmpresa) return false;
    if (filterVaga !== "Todas" && c.vaga !== filterVaga) return false;
    if (search.trim() && !(c.name||"").toLowerCase().includes(search.trim().toLowerCase())) return false;
    return true;
  });

  const handleDownload = async (c) => {
    setDownloadingId(c.id);
    const r = await DB.getByField("disc_results", "candidate_id", c.id);
    setDownloadingId(null);
    if (!r) { setMsg("Resultado não encontrado"); setTimeout(()=>setMsg(""),2000); return; }
    downloadResultDocument(c, r);
  };

  const handleDelete = async (c) => {
    await DB.delete("candidates", c.id);
    setDeleteC(null);
    setMsg("Candidato removido");
    onRefresh();
    setTimeout(()=>setMsg(""),3000);
  };

  const copyInviteLink = async (c) => {
    const link = `${window.location.origin}${window.location.pathname}?token=${c.id}`;
    try { await navigator.clipboard.writeText(link); setMsg("Link copiado!"); setTimeout(()=>setMsg(""),2000); } catch {}
  };

  const emailInviteLink = (c) => {
    const to = prompt("E-mail do candidato:");
    if (!to) return;
    const link = `${window.location.origin}${window.location.pathname}?token=${c.id}`;
    const subject = "Teste de Perfil Comportamental — Dux Logistics";
    const body = `Olá,\n\nVocê está participando do nosso processo seletivo na Dux Logistics.\n\nPor favor, acesse o link abaixo para realizar o teste de perfil comportamental (leva cerca de 10 minutos):\n\n${link}\n\nAtenciosamente,\nEquipe de Recrutamento e Seleção\nDux Logistics`;
    window.location.href = `mailto:${encodeURIComponent(to)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
  };

  return (
    <div>
      <div style={{ display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:8 }}>
        <div>
          <div style={pageTitle}>Candidatos</div>
          <div style={pageSub}>Gere links, acompanhe status e veja os resultados</div>
        </div>
        <button style={btnP} onClick={()=>setShowNew(true)}>+ Gerar Link</button>
      </div>
      {msg && <div style={okBox}>{msg}</div>}
      <div style={{ marginBottom:20,display:"flex",gap:12,flexWrap:"wrap",alignItems:"center" }}>
        <input style={{ ...input,width:220,marginBottom:0,padding:"8px 12px",fontSize:13 }}
          placeholder="Pesquisar por nome..." value={search} onChange={e=>setSearch(e.target.value)} onFocus={focusH} onBlur={blurH}/>
        <div style={{ display:"flex",gap:8,flexWrap:"wrap" }}>
          {["Todos","Pendente","Respondido"].map(s => (
            <button key={s} onClick={()=>setFilterStatus(s)}
              style={{ padding:"8px 16px",borderRadius:20,fontSize:13,fontWeight:600,border:`1.5px solid ${filterStatus===s?T.primary:T.border}`,background:filterStatus===s?T.primaryLight:"transparent",color:filterStatus===s?T.primary:T.textSec,cursor:"pointer",fontFamily:T.font }}>
              {s}
            </button>
          ))}
        </div>
        <select value={filterEmpresa} onChange={e=>setFilterEmpresa(e.target.value)}
          style={{ ...select,width:"auto",minWidth:200,marginBottom:0,padding:"8px 12px",fontSize:13 }}>
          <option value="Todas">Todas as empresas</option>
          {EMPRESAS_DUX.map(e => <option key={e} value={e}>{e}</option>)}
        </select>
        <select value={filterVaga} onChange={e=>setFilterVaga(e.target.value)}
          style={{ ...select,width:"auto",minWidth:180,marginBottom:0,padding:"8px 12px",fontSize:13 }}>
          <option value="Todas">Todas as vagas</option>
          {vagasList.map(v => <option key={v} value={v}>{v}</option>)}
        </select>
      </div>
      {filtered.length === 0 ? (
        <div style={{ ...card,textAlign:"center",padding:"60px 20px" }}>
          <div style={{ fontSize:18,fontWeight:600,marginBottom:8 }}>Nenhum candidato encontrado</div>
          <div style={{ color:T.textSec }}>Clique em "Gerar Link" para convidar o primeiro candidato.</div>
        </div>
      ) : (
        <div style={{ ...card,padding:0,overflow:"hidden" }}>
          <div style={{ overflowX:"auto" }}>
          <table style={{ width:"100%",borderCollapse:"separate",borderSpacing:0,minWidth:1180 }}>
            <thead><tr>
              <th style={thS}>Nome</th><th style={thS}>CPF</th><th style={thS}>E-mail</th><th style={thS}>Empresa</th><th style={thS}>Vaga</th><th style={thS}>Perfil</th><th style={thS}>Status</th><th style={thS}>Criado em</th><th style={thS}>Respondido em</th><th style={{ ...thS,textAlign:"right" }}>Ações</th>
            </tr></thead>
            <tbody>
              {filtered.map(c => (
                <tr key={c.id} onMouseEnter={e=>e.currentTarget.style.background=T.surfaceHover} onMouseLeave={e=>e.currentTarget.style.background="transparent"}>
                  <td style={{ ...tdS,fontWeight:500 }}>{c.name || <span style={{ color:T.textMut,fontStyle:"italic" }}>Aguardando resposta</span>}</td>
                  <td style={tdS}>{c.cpf?formatCpf(c.cpf):"-"}</td>
                  <td style={tdS}>{c.email||"-"}</td>
                  <td style={tdS}>{c.empresa ? <span style={badge(c.empresa)}>{c.empresa}</span> : "-"}</td>
                  <td style={tdS}>{c.vaga||"-"}</td>
                  <td style={tdS}>
                    {c.perfil ? (
                      <span style={{ display:"inline-flex",alignItems:"center",gap:6,padding:"4px 10px 4px 4px",borderRadius:20,background:DISC_PROFILES[c.perfil]?.color+"22",fontWeight:600,fontSize:12,color:DISC_PROFILES[c.perfil]?.color }}>
                        <span style={{ width:20,height:20,borderRadius:6,background:DISC_PROFILES[c.perfil]?.color,color:"#fff",display:"flex",alignItems:"center",justifyContent:"center",fontSize:11,fontWeight:800 }}>{c.perfil}</span>
                        {DISC_PROFILES[c.perfil]?.name}
                      </span>
                    ) : "-"}
                  </td>
                  <td style={tdS}><span style={badge(c.status==="Respondido"?"Positivo":"Para melhorar")}>{c.status}</span></td>
                  <td style={{ ...tdS,fontSize:13,color:T.textSec }}>{fmtDate(c.created_at)}</td>
                  <td style={{ ...tdS,fontSize:13,color:T.textSec }}>{c.answered_at ? fmtDate(c.answered_at) : "-"}</td>
                  <td style={{ ...tdS,textAlign:"right",whiteSpace:"nowrap" }}>
                    {c.status==="Respondido" ? (
                      <>
                        <button style={btnSm} onClick={()=>setViewResult(c)} title="Ver resultado"><Icon name="eye" size={14}/></button>
                        <button style={{ ...btnSm,marginLeft:6 }} onClick={()=>setViewAnswers(c)} title="Ver respostas"><Icon name="feedback" size={14}/></button>
                        <button style={{ ...btnSm,marginLeft:6,opacity:downloadingId===c.id?.5:1 }} onClick={()=>handleDownload(c)} disabled={downloadingId===c.id} title="Baixar resultado"><Icon name="download" size={14}/></button>
                      </>
                    ) : (
                      <>
                        <button style={btnSm} onClick={()=>copyInviteLink(c)} title="Copiar link"><Icon name="download" size={14}/></button>
                        <button style={{ ...btnSm,marginLeft:6 }} onClick={()=>emailInviteLink(c)} title="Enviar por e-mail"><Icon name="mail" size={14}/></button>
                      </>
                    )}
                    {isAdmin && <button style={{ ...btnD,marginLeft:6 }} onClick={()=>setDeleteC(c)} title="Apagar"><Icon name="trash" size={14}/></button>}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          </div>
        </div>
      )}
      {showNew && <NewCandidateModal onClose={()=>setShowNew(false)} onSave={onRefresh} currentUser={currentUser} vagasExistentes={vagasList}/>}
      {viewResult && <ResultModal candidate={viewResult} onClose={()=>setViewResult(null)}/>}
      {viewAnswers && <AnswersModal candidate={viewAnswers} onClose={()=>setViewAnswers(null)}/>}
      {deleteC && (
        <Modal onClose={()=>setDeleteC(null)}>
          <div style={{ fontSize:20,fontWeight:700,marginBottom:4 }}>Tem certeza que quer excluir?</div>
          <div style={{ fontSize:13,color:T.textSec,marginBottom:24 }}>O convite/resultado de <strong>{deleteC.name || "candidato pendente"}</strong> será apagado permanentemente.</div>
          <div style={{ display:"flex",gap:12,justifyContent:"flex-end" }}>
            <button style={btnO} onClick={()=>setDeleteC(null)}>Cancelar</button>
            <button style={{ ...btnP,background:T.danger }} onClick={()=>handleDelete(deleteC)}>Sim, excluir</button>
          </div>
        </Modal>
      )}
    </div>
  );
};

// ============================================================
// PAGE: USERS (RH team)
// ============================================================
const UsersPage = ({ users, onRefresh, isAdmin }) => {
  const [showNew, setShowNew] = useState(false);
  const [editUser, setEditUser] = useState(null);

  return (
    <div>
      <div style={{ display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:20 }}>
        <div>
          <div style={pageTitle}>Usuários</div>
          <div style={pageSub}>Pessoas da equipe de RH com acesso ao painel</div>
        </div>
        {isAdmin && <button style={btnP} onClick={()=>setShowNew(true)}>+ Novo Usuário</button>}
      </div>
      <div style={{ ...card,padding:0,overflow:"hidden" }}>
        <table style={{ width:"100%",borderCollapse:"separate",borderSpacing:0 }}>
          <thead><tr><th style={thS}>Nome</th><th style={thS}>Usuário</th><th style={thS}>Perfil</th>{isAdmin && <th style={{ ...thS,textAlign:"right" }}>Ações</th>}</tr></thead>
          <tbody>
            {users.map(u => (
              <tr key={u.id}>
                <td style={{ ...tdS,fontWeight:500 }}>{u.name}</td>
                <td style={tdS}>{u.username}</td>
                <td style={tdS}><span style={roleBadge(u.role)}>{u.role==="admin"?"Administrador":"RH"}</span></td>
                {isAdmin && <td style={{ ...tdS,textAlign:"right" }}><button style={btnSm} onClick={()=>setEditUser(u)} title="Editar"><Icon name="edit" size={14}/></button></td>}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {showNew && <UserModal onClose={()=>setShowNew(false)} onSave={()=>{setShowNew(false);onRefresh();}}/>}
      {editUser && <UserModal editUser={editUser} onClose={()=>setEditUser(null)} onSave={()=>{setEditUser(null);onRefresh();}}/>}
    </div>
  );
};

// ============================================================
// MAIN APP
// ============================================================
export default function App() {
  const [currentUser, setCurrentUser] = useState(() => {
    try { const s = sessionStorage.getItem("disc_session"); return s ? JSON.parse(s) : null; } catch { return null; }
  });
  const [page, setPage] = useState("dashboard");
  const [users, setUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [ready, setReady] = useState(false);
  const [showChangePw, setShowChangePw] = useState(false);

  // Public candidate link check
  const [tokenChecking, setTokenChecking] = useState(true);
  const [invite, setInvite] = useState(null);
  const [inviteError, setInviteError] = useState("");

  const loadUsers = useCallback(async () => { setUsers(await DB.getAll("users")); },[]);
  const loadCandidates = useCallback(async () => { setCandidates(await DB.getAll("candidates")); },[]);
  const loadAll = useCallback(async () => { await loadUsers(); await loadCandidates(); },[loadUsers,loadCandidates]);

  useEffect(() => { setReady(true); },[]);
  useEffect(() => { if(currentUser) loadAll(); },[currentUser,loadAll]);

  useEffect(() => {
    (async () => {
      const params = new URLSearchParams(window.location.search);
      const tokenId = params.get("token");
      if (tokenId) {
        const c = await DB.getByField("candidates","id",tokenId);
        if (!c) { setInviteError("Este link não existe."); }
        else if (c.status === "Respondido") { setInviteError("Este teste já foi respondido anteriormente."); }
        else { setInvite(c); }
      }
      setTokenChecking(false);
    })();
  },[]);

  // Public flow takes priority over everything else
  if (tokenChecking) return <div style={{ fontFamily:T.font,background:"#F7F5F2",display:"flex",alignItems:"center",justifyContent:"center",minHeight:"100vh" }}>Carregando...</div>;
  if (invite) return <CandidateTestPublic invite={invite}/>;
  if (inviteError) return <InvalidLinkScreen reason={inviteError}/>;

  const handleLogin = (user) => { sessionStorage.setItem("disc_session", JSON.stringify(user)); setCurrentUser(user); };
  const handleLogout = () => { sessionStorage.removeItem("disc_session"); setCurrentUser(null); setPage("dashboard"); };

  if (!ready) return <div style={{ fontFamily:T.font,background:T.bg,color:T.textSec,display:"flex",alignItems:"center",justifyContent:"center",minHeight:"100vh" }}>Iniciando sistema...</div>;
  if (!currentUser) return <div style={{ fontFamily:T.font }}><LoginScreen onLogin={handleLogin}/></div>;

  const isAdmin = currentUser.role === "admin";
  const navItems = [
    { id:"dashboard",label:"Dashboard",icon:"home" },
    { id:"candidates",label:"Candidatos",icon:"people" },
    ...(isAdmin?[{ id:"users",label:"Usuários",icon:"users" }]:[]),
  ];

  return (
    <div style={{ fontFamily:T.font,background:T.bg,color:T.text,minHeight:"100vh",lineHeight:1.5 }}>
      <div style={{ display:"flex",minHeight:"100vh" }}>
        <div style={{ width:260,background:T.surface,borderRight:`1px solid ${T.border}`,padding:"32px 0",display:"flex",flexDirection:"column",flexShrink:0 }}>
          <div style={{ padding:"0 24px",marginBottom:40 }}>
            <img src={LOGO} alt="Dux Logistics" style={{ height:36,marginBottom:8,borderRadius:4 }}/>
            <div style={{ fontSize:11,color:T.textMut,marginTop:4,letterSpacing:"1px",textTransform:"uppercase" }}>Teste DISC — Candidatos</div>
          </div>
          <nav>
            {navItems.map(n => (
              <div key={n.id} onClick={()=>setPage(n.id)}
                style={{ display:"flex",alignItems:"center",gap:12,padding:"12px 24px",fontSize:14,fontWeight:page===n.id?600:500,color:page===n.id?T.primary:T.textSec,background:page===n.id?T.primaryLight:"transparent",borderLeft:page===n.id?`3px solid ${T.primary}`:"3px solid transparent",cursor:"pointer",transition:"all .15s" }}>
                <Icon name={n.icon} size={18}/>{n.label}
              </div>
            ))}
          </nav>
          <div style={{ marginTop:"auto",padding:"20px 24px",borderTop:`1px solid ${T.border}`,display:"flex",alignItems:"center",gap:12 }}>
            <div style={avatarS(isAdmin?T.primary:T.success)}>{currentUser.name.charAt(0).toUpperCase()}</div>
            <div style={{ flex:1,minWidth:0 }}>
              <div style={{ fontSize:14,fontWeight:600,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis" }}>{currentUser.name}</div>
              <div style={{ fontSize:11,color:T.textMut }}>{isAdmin?"Administrador":"RH"}</div>
            </div>
            <div style={{ cursor:"pointer",color:T.textMut,padding:4 }} onClick={()=>setShowChangePw(true)} title="Alterar senha"><Icon name="key" size={18}/></div>
            <div style={{ cursor:"pointer",color:T.textMut,padding:4 }} onClick={handleLogout} title="Sair"><Icon name="logout" size={18}/></div>
          </div>
        </div>
        <div style={{ flex:1,padding:"40px 48px",overflowY:"auto",maxHeight:"100vh",boxSizing:"border-box" }}>
          {page==="dashboard" && <DashboardPage candidates={candidates}/>}
          {page==="candidates" && <CandidatesPage candidates={candidates} onRefresh={loadAll} currentUser={currentUser} isAdmin={isAdmin}/>}
          {page==="users" && isAdmin && <UsersPage users={users} onRefresh={loadAll} isAdmin={isAdmin}/>}
        </div>
      </div>
      {showChangePw && <ChangePasswordModal currentUser={currentUser} onClose={()=>setShowChangePw(false)}/>}
    </div>
  );
}
